    );
    assert_eq!(editor.display_text(cx), "🟥🟧⋯🟦🟪\nab⋯e\nαβ⋯ε");

    editor.move_right(&MoveRight, window, cx);
    assert_eq!(display_ranges(editor, cx), &[empty_range(0, "🟥".len())]);
    editor.move_right(&MoveRight, window, cx);
    assert_eq!(display_ranges(editor, cx), &[empty_range(0, "🟥🟧".len())]);
